package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;public final class MitigateEffectSpec implements EffectSpec{public enum MitigationStackingPolicy{KEEP_STRONGER}private final StableId effectId;private final int percent;private final DurationSpec duration;private final MitigationStackingPolicy stacking;public MitigateEffectSpec(StableId id,int percent,DurationSpec duration,MitigationStackingPolicy stacking){if(id==null||duration==null||stacking==null||percent<1||percent>75)throw new IllegalArgumentException("invalid mitigation fields");effectId=id;this.percent=percent;this.duration=duration;this.stacking=stacking;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.RECOVERY_DEFENSE;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.MITIGATE;}public int percent(){return percent;}public DurationSpec duration(){return duration;}public MitigationStackingPolicy stacking(){return stacking;}}
